{"content":"// Build-time preprocessing: converts data/*.json (read-only) into compact
// runtime files under public/data/ (which Vite copies to dist/data/).
// Binary element packs are Float32LE: [uint32 N][N x F floats].
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const IN = join(root, 'data');
const OUT = join(root, 'public', 'data');
mkdirSync(OUT, { recursive: true });

const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : NaN);
const r6 = (v) => Math.round(v * 1e6) / 1e6;

function writeBin(name, rows, stride) {
  const buf = Buffer.alloc(4 + rows.length * stride * 4);
  buf.writeUInt32LE(rows.length, 0);
  let o = 4;
  for (const row of rows) {
    for (let k = 0; k < stride; k++) {
      const v = row[k];
      buf.writeFloatLE(Number.isFinite(v) ? v : NaN, o);
      o += 4;
    }
  }
  writeFileSync(join(OUT, name), buf);
  console.log(name, rows.length, 'rows,', (buf.length / 1024).toFixed(0) + ' KiB');
}

// --- asteroids ---
const asteroids = JSON.parse(readFileSync(join(IN, 'asteroids.json'), 'utf8'));
writeBin(
  'asteroids.bin',
  asteroids.map((o) => [o.a, o.e, o.i, o.om, o.w, o.ma, o.epoch, o.n, num(o.H), num(o.diameter), num(o.moid)]),
  11,
);
writeFileSync(
  join(OUT, 'asteroids-meta.json'),
  JSON.stringify({
    pdes: asteroids.map((o) => o.pdes),
    name: asteroids.map((o) => o.name ?? null),
    cls: asteroids.map((o) => o.class ?? '?'),
    pha: asteroids.map((o) => (o.pha ? 1 : 0)),
  }),
);
console.log('asteroids-meta.json written');

// --- comets ---
const comets = JSON.parse(readFileSync(join(IN, 'comets.json'), 'utf8'));
writeBin(
  'comets.bin',
  comets.map((o) => [
    num(o.a), o.e, o.i, o.om, o.w, num(o.ma), num(o.epoch), num(o.n),
    num(o.q), num(o.tp), num(o.M1), num(o.diameter), num(o.per),
  ]),
  13,
);
writeFileSync(
  join(OUT, 'comets-meta.json'),
  JSON.stringify({
    pdes: comets.map((o) => o.pdes),
    name: comets.map((o) => o.full_name ?? o.pdes),
    cls: comets.map((o) => o.class ?? '?'),
  }),
);
console.log('comets-meta.json written');

// --- close approaches: per-object map + global time-sorted timeline ---
const cas = JSON.parse(readFileSync(join(IN, 'close-approaches.json'), 'utf8'));
const byDes = {};
const timeline = [];
for (const c of cas) {
  const e = [Math.round(c.jd * 1e4) / 1e4, r6(c.dist), Math.round(c.v_rel * 1e3) / 1e3];
  (byDes[c.des] ??= []).push(e);
  timeline.push([e[0], c.des, e[1]]);
}
for (const k of Object.keys(byDes)) byDes[k].sort((a, b) => a[0] - b[0]);
timeline.sort((a, b) => a[0] - b[0]);
writeFileSync(join(OUT, 'ca-by-des.json'), JSON.stringify(byDes));
writeFileSync(join(OUT, 'ca-timeline.json'), JSON.stringify(timeline));
console.log('ca files written:', Object.keys(byDes).length, 'objects,', timeline.length, 'events');

// --- small files copied verbatim ---
for (const f of ['planets.json', 'sentry.json']) copyFileSync(join(IN, f), join(OUT, f));

// --- manifest ---
const sentry = JSON.parse(readFileSync(join(IN, 'sentry.json'), 'utf8'));
writeFileSync(
  join(OUT, 'manifest.json'),
  JSON.stringify({
    asteroids: asteroids.length,
    comets: comets.length,
    closeApproachEvents: cas.length,
    closeApproachObjects: Object.keys(byDes).length,
    sentry: sentry.length,
    jdMin: timeline[0][0],
    jdMax: timeline[timeline.length - 1][0],
    pha: asteroids.filter((o) => o.pha).length,
  }),
);
console.log('manifest written — done');
","path":"scripts/preprocess.mjs"}

{"content":"// Runtime data loading (relative fetch URLs — the site is served from a sub-path).
import type { Elements } from './orbit';

const base = new URL('data/', document.baseURI).toString();
async function get(path: string): Promise<Response> {
  const r = await fetch(base + path);
  if (!r.ok) throw new Error(`failed to load ${path}: ${r.status}`);
  return r;
}

export interface PlanetRec extends Elements {
  name: string;
  radiusKm: number;
  per: number;
}

export interface BodyStore {
  n: number;
  els: Elements[]; // lightweight views over packed arrays
  pdes: string[];
  label: string[]; // display name
  cls: string[];
  pha: Uint8Array; // asteroids only (zeros for comets)
  H: Float32Array;
  diam: Float32Array;
  moid: Float32Array; // asteroids only
  M1: Float32Array; // comets only
  per: Float32Array;
  byPdes: Map<string, number>;
}

function packAsteroids(buf: ArrayBuffer, meta: any): BodyStore {
  const dv = new DataView(buf);
  const n = dv.getUint32(0, true);
  const els: Elements[] = new Array(n);
  const H = new Float32Array(n);
  const diam = new Float32Array(n);
  const moid = new Float32Array(n);
  const pha = new Uint8Array(n);
  let o = 4;
  const g = () => {
    const v = dv.getFloat32(o, true);
    o += 4;
    return v;
  };
  for (let k = 0; k < n; k++) {
    const a = g(), e = g(), i = g(), om = g(), w = g(), ma = g(), epoch = g(), nn = g();
    H[k] = g();
    diam[k] = g();
    moid[k] = g();
    els[k] = { a, e, i, om, w, ma, epoch, n: nn, tp: NaN, q: NaN };
    pha[k] = meta.pha[k] ? 1 : 0;
  }
  return finish(n, els, meta.pdes, meta.name, meta.cls, pha, H, diam, moid, new Float32Array(n).fill(NaN), new Float32Array(n).fill(NaN));
}

function packComets(buf: ArrayBuffer, meta: any): BodyStore {
  const dv = new DataView(buf);
  const n = dv.getUint32(0, true);
  const els: Elements[] = new Array(n);
  const M1 = new Float32Array(n);
  const diam = new Float32Array(n);
  const per = new Float32Array(n);
  let o = 4;
  const g = () => {
    const v = dv.getFloat32(o, true);
    o += 4;
    return v;
  };
  for (let k = 0; k < n; k++) {
    const a = g(), e = g(), i = g(), om = g(), w = g(), ma = g(), epoch = g(), nn = g();
    const q = g(), tp = g(), m1 = g(), dm = g(), pr = g();
    els[k] = { a, e, i, om, w, ma, epoch, n: nn, tp, q };
    M1[k] = m1;
    diam[k] = dm;
    per[k] = pr;
  }
  return finish(n, els, meta.pdes, meta.name, meta.cls, new Uint8Array(n), new Float32Array(n).fill(NaN), diam, new Float32Array(n).fill(NaN), M1, per);
}

function finish(
  n: number, els: Elements[], pdes: string[], names: (string | null)[], cls: string[],
  pha: Uint8Array, H: Float32Array, diam: Float32Array, moid: Float32Array,
  M1: Float32Array, per: Float32Array,
): BodyStore {
  const label = new Array<string>(n);
  for (let k = 0; k < n; k++) label[k] = names[k] || pdes[k];
  const byPdes = new Map<string, number>();
  for (let k = 0; k < n; k++) if (!byPdes.has(pdes[k])) byPdes.set(pdes[k], k);
  return { n, els, pdes, label, cls, pha, H, diam, moid, M1, per, byPdes };
}

export interface SentryRec {
  des: string;
  fullname: string;
  ip: number;
  ps_cum: number;
  ps_max: number;
  ts_max: number;
  range: string;
  n_imp: number;
  diameter: number | null;
}

export interface Dataset {
  planets: PlanetRec[];
  asteroids: BodyStore;
  comets: BodyStore;
  caByDes: Record<string, [number, number, number][]>; // [jd, distAu, vrel]
  caTimeline: [number, string, number][]; // sorted [jd, des, dist]
  sentry: SentryRec[];
  sentryByDes: Map<string, SentryRec>;
  manifest: any;
}

export async function loadDataset(onProgress: (msg: string) => void): Promise<Dataset> {
  onProgress('Loading planets…');
  const planetsRaw = await (await get('planets.json')).json();
  const planets: PlanetRec[] = planetsRaw.map((p: any) => ({
    name: p.name, radiusKm: p.radius_km, per: p.per,
    a: p.a, e: p.e, i: p.i, om: p.om, w: p.w, ma: p.ma,
    epoch: p.epoch, n: p.n, tp: NaN, q: NaN,
  }));
  onProgress('Loading asteroids…');
  const [abuf, ameta] = await Promise.all([
    (await get('asteroids.bin')).arrayBuffer(),
    (await get('asteroids-meta.json')).json(),
  ]);
  const asteroids = packAsteroids(abuf, ameta);
  onProgress('Loading comets…');
  const [cbuf, cmeta] = await Promise.all([
    (await get('comets.bin')).arrayBuffer(),
    (await get('comets-meta.json')).json(),
  ]);
  const comets = packComets(cbuf, cmeta);
  onProgress('Loading close approaches…');
  const [caByDes, caTimeline] = await Promise.all([
    (await get('ca-by-des.json')).json(),
    (await get('ca-timeline.json')).json(),
  ]);
  onProgress('Loading impact-risk data…');
  const sentry: SentryRec[] = await (await get('sentry.json')).json();
  const sentryByDes = new Map(sentry.map((s) => [s.des, s]));
  const manifest = await (await get('manifest.json')).json();
  onProgress('Ready');
  return { planets, asteroids, comets, caByDes, caTimeline, sentry, sentryByDes, manifest };
}

/** Binary-search the sorted CA timeline for the first index with jd >= target. */
export function timelineIndex(timeline: [number, string, number][], target: number): number {
  let lo = 0;
  let hi = timeline.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (timeline[mid][0] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
