{"content":":root {
  --bg: #04060c;
  --panel: rgba(10, 16, 28, 0.88);
  --line: #223349;
  --txt: #d7e2f2;
  --dim: #8fa1b8;
  --acc: #4da6ff;
  --red: #ff5252;
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--txt);
  font: 13px/1.45 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  overflow: hidden;
}
#view { position: fixed; inset: 0; }
#view canvas { display: block; }
.labels { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.planet-label, .sel-label {
  position: absolute;
  transform: translate(-50%, -130%);
  font-size: 11px;
  color: var(--txt);
  text-shadow: 0 0 4px #000, 0 0 2px #000;
  white-space: nowrap;
  pointer-events: none;
}
.sel-label { color: #fff; font-weight: 600; }

#topbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 10;
  display: flex; align-items: center; gap: 10px;
  padding: 6px 12px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(6px);
}
.brand { font-weight: 700; letter-spacing: 0.5px; color: #fff; white-space: nowrap; }
.time-ctl { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
button {
  background: #16233a; color: var(--txt);
  border: 1px solid var(--line); border-radius: 4px;
  padding: 3px 9px; cursor: pointer; font-size: 12px;
}
button:hover { border-color: var(--acc); color: #fff; }
button.active { background: #1d3a5f; border-color: var(--acc); color: #fff; }
#btn-play { min-width: 38px; }
.speed { display: flex; align-items: center; gap: 6px; color: var(--dim); }
#speed { width: 110px; }
#speed-label { min-width: 92px; color: var(--txt); }
#date-input { width: 104px; background: #0a1220; color: var(--txt); border: 1px solid var(--line); border-radius: 4px; padding: 3px 6px; }
#clock { margin-left: auto; font-variant-numeric: tabular-nums; color: #fff; white-space: nowrap; }

#scrubbar {
  position: fixed; top: 41px; left: 0; right: 0; z-index: 9;
  display: flex; align-items: center; gap: 8px;
  padding: 2px 12px;
  background: rgba(10, 16, 28, 0.6);
  color: var(--dim); font-size: 11px;
}
#scrub { flex: 1; }

aside {
  position: fixed; top: 66px; bottom: 30px; z-index: 10;
  width: 248px; overflow-y: auto;
  background: var(--panel);
  border: 1px solid var(--line); border-radius: 8px;
  padding: 10px 12px;
  backdrop-filter: blur(6px);
}
#left { left: 10px; }
#right { right: 10px; width: 300px; }
aside h2 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.6px; color: var(--dim); margin: 14px 0 6px; }
aside h2:first-child { margin-top: 0; }
.row { display: flex; align-items: center; gap: 6px; margin: 4px 0; cursor: pointer; }
.row input[type="range"] { flex: 1; }
#search { width: 100%; background: #0a1220; color: var(--txt); border: 1px solid var(--line); border-radius: 4px; padding: 5px 7px; }
#search-results { list-style: none; margin: 6px 0 0; padding: 0; max-height: 180px; overflow-y: auto; }
#search-results li { padding: 3px 6px; border-radius: 4px; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#search-results li:hover { background: #1d3a5f; }
#search-results .cls { color: var(--dim); font-size: 11px; margin-left: 6px; }
#match-count { color: var(--acc); text-transform: none; }
#f-classes { display: flex; flex-wrap: wrap; gap: 2px 10px; margin: 4px 0; }
#f-classes label { display: flex; gap: 4px; align-items: center; cursor: pointer; }
.legend { display: flex; flex-wrap: wrap; gap: 4px 10px; margin-top: 8px; color: var(--dim); font-size: 11px; }
.legend i { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 4px; }

#d-badges { display: flex; gap: 6px; flex-wrap: wrap; margin: 6px 0; }
.badge { font-size: 11px; padding: 1px 8px; border-radius: 10px; border: 1px solid var(--line); color: var(--dim); }
.badge.pha { color: #ffb3b3; border-color: var(--red); }
.badge.sentry { color: #eec2ff; border-color: #c86aff; }
.badge.cls { color: var(--txt); }
#d-actions { display: flex; gap: 6px; margin: 8px 0; }
#d-body table { width: 100%; border-collapse: collapse; font-size: 12px; }
#d-body td { padding: 2px 4px; border-bottom: 1px solid #141f33; }
#d-body td:first-child { color: var(--dim); width: 42%; }
#d-body td:last-child { text-align: right; font-variant-numeric: tabular-nums; }
#d-ca table { width: 100%; border-collapse: collapse; font-size: 12px; }
#d-ca th { color: var(--dim); font-weight: 400; text-align: right; padding: 2px 4px; }
#d-ca th:first-child, #d-ca td:first-child { text-align: left; }
#d-ca td { padding: 2px 4px; text-align: right; font-variant-numeric: tabular-nums; border-bottom: 1px solid #141f33; }
#d-ca tr.future td:first-child { color: var(--acc); cursor: pointer; }
#d-ca .none, #up-list .none { color: var(--dim); }

#upcoming {
  position: fixed; left: 268px; bottom: 30px; z-index: 10;
  width: 300px; max-height: 40vh; overflow-y: auto;
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  padding: 8px 12px; backdrop-filter: blur(6px);
}
#upcoming h2 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.6px; color: var(--dim); margin: 0 0 6px; }
#up-list { list-style: none; margin: 0; padding: 0; font-size: 12px; }
#up-list li { padding: 3px 4px; border-bottom: 1px solid #141f33; cursor: pointer; font-variant-numeric: tabular-nums; }
#up-list li:hover { background: #1d3a5f; }

#statusbar {
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 10;
  display: flex; justify-content: space-between; gap: 12px;
  padding: 4px 12px;
  background: var(--panel); border-top: 1px solid var(--line);
  color: var(--dim); font-size: 11px; white-space: nowrap; overflow: hidden;
}
#hint { overflow: hidden; text-overflow: ellipsis; }

#loading {
  position: fixed; inset: 0; z-index: 50;
  display: flex; align-items: center; justify-content: center;
  background: var(--bg);
}
.load-box { text-align: center; }
.load-box h1 { color: #fff; letter-spacing: 1px; }
#load-msg { color: var(--dim); }

#help {
  position: fixed; inset: 0; z-index: 40;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0, 0, 0, 0.6);
}
.help-box { max-width: 560px; background: #0b1322; border: 1px solid var(--line); border-radius: 10px; padding: 20px 24px; }
.help-box h1 { margin-top: 0; color: #fff; }
.help-box li { margin: 4px 0; }
.hidden { display: none !important; }

@media (max-width: 900px) {
  #left { display: none; }
  #upcoming { left: 10px; }
  #hint { display: none; }
}
